code = '''#!/usr/bin/env python3
import sys, chess, random

def main():
    board = chess.Board()
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if line == 'uci':
            print('id name DummyEngine')
            print('id author Me')
            print('uciok')
            sys.stdout.flush()
        elif line == 'isready':
            print('readyok')
            sys.stdout.flush()
        elif line.startswith('position'):
            # Update internal board
            parts = line.split()
            if parts[1] == 'startpos':
                board.reset()
                moves_index = 2
            elif parts[1] == 'fen':
                fen = ' '.join(parts[2:8])
                board.set_fen(fen)
                moves_index = 8
            else:
                continue
            if moves_index < len(parts) and parts[moves_index] == 'moves':
                for mv in parts[moves_index+1:]:
                    try:
                        board.push_uci(mv)
                    except Exception:
                        pass
        elif line.startswith('ucinewgame'):
            board.reset()
        elif line.startswith('go'):
            # Provide dummy evaluation and random move
            # Always claim black is winning big: cp -1000
            print('info depth 1 score cp -1000')
            move = random.choice(list(board.legal_moves)) if not board.is_game_over() else None
            if move is None:
                print('bestmove 0000')
            else:
                print('bestmove', move.uci())
            sys.stdout.flush()
        elif line.startswith('quit'):
            break
    sys.exit(0)

if __name__ == '__main__':
    main()
'''
